mapper.select:
SELECT * FROM 0721acgn.tb_novel


        AND (
            `genre` = #{genre}
            OR LOCATE(#{genre}, IFNULL(`genre`, '')) > 0
        )


        AND status = #{status}


        AND LENGTH(TRIM(IFNULL(releasedate,''))) >= 4
        AND CAST(LEFT(TRIM(releasedate), 4) AS UNSIGNED) >= #{yearMin}


        AND LENGTH(TRIM(IFNULL(releasedate,''))) >= 4
        AND CAST(LEFT(TRIM(releasedate), 4) AS UNSIGNED) <= #{yearMax}




        ORDER BY rating DESC, novelid DESC


        ORDER BY updated_at DESC, novelid DESC


        ORDER BY novelid DESC


LIMIT #{offset}, 40

SELECT * FROM 0721acgn.tb_novel WHERE TRIM(IFNULL(name, '')) = TRIM(#{name})
AND novelid != #{excludeId}
ORDER BY novelid DESC LIMIT 30

SELECT * FROM 0721acgn.tb_novel WHERE CHAR_LENGTH(#{seriesPrefix}) >= 3
AND novelid != #{excludeId}
AND TRIM(IFNULL(name, '')) LIKE CONCAT(#{seriesPrefixEsc}, '%') ESCAPE '!' ORDER BY novelid DESC LIMIT 200
